    [Theory]
    [MemberData(nameof(Vectors))]
    public void EveryModeDecodesAsBcdecDoes(string block, string halves, string signed)
    {
        byte[] bytes = Convert.FromHexString(block);
        var got = new ushort[48];
        Bc6h.Halves(bytes, got, signed == "1");
        string said = string.Concat(got.Select(one => one.ToString("X4", CultureInfo.InvariantCulture)));
        Assert.Equal(halves, said);
    }
